/*--Header--*/
$(document).ready(function () {

    //skip part
    $('#skip a').click(function () {
        var scroll;
        if ($("div").hasClass("sectiontitle")) {
            scroll = ".sectiontitle";
        } else {
            scroll = ".breadcrumb"; /*Against MCADEF-74, Skip to Main Content to bypass image main-content*/
        }
        $([document.documentElement, document.body]).animate({
            scrollTop: $(scroll).offset().top
        }, 700);
    });

  $(document).ready(function () {
    var $toggle = $('#themesbox');
    var $text = $('#themeText');
    var STORAGE_KEY = 'style_theme';

    var saved = localStorage.getItem(STORAGE_KEY) || 'light';
    var isDark = (saved === 'dark');

    $toggle.prop('checked', isDark);
    $('body').toggleClass('dark', isDark);
    if ($text.length) $text.text(isDark ? 'Dark Mode' : 'Light Mode');

    if (typeof switch_style === 'function') {
      switch_style(isDark ? 'grey' : 'blue');
    }

    $toggle.on('change', function () {
      var checked = $(this).is(':checked');

      $('body').toggleClass('dark', checked);
      if ($text.length) $text.text(checked ? 'Dark Mode' : 'Light Mode');

      localStorage.setItem(STORAGE_KEY, checked ? 'dark' : 'light');

      if (typeof switch_style === 'function') {
        switch_style(checked ? 'grey' : 'blue');
      }
    });
  });

  var fontcounter = 1;
  var onloadfontcounter;
  //handle the null and undefined condition
  if (localStorage.getItem("fontcountsave") == null) {
    localStorage.setItem("fontcountsave", "1");

    onloadfontcounter = 1;
  }
  else {
    onloadfontcounter = localStorage.getItem("fontcountsave");
  }
  if (onloadfontcounter >= 3) {
    //disable the plus button
  }
  if (onloadfontcounter <= 0) {
    //disable the minus button
  }
  $('*').css("font-size", function () {

    onloadfont = $(this).css('font-size');

    if (onloadfontcounter == 0) {
      return parseInt(onloadfont) - 1 + 'px';
    }
    else if (onloadfontcounter == 1) {
      return parseInt(onloadfont);
    }
    else if (onloadfontcounter == 2) {
      return parseInt(onloadfont) + 1 + 'px';
    }
    else if (onloadfontcounter == 3) {
      return parseInt($(this).css('font-size')) + 2 + 'px';
    }
  });
});

function incFunc() {
  var fontcounter = localStorage.getItem("fontcountsave");
  if (fontcounter < 3) {
    fontcounter++;
    $('*').css("font-size", function () {
      return parseInt($(this).css('font-size')) + 1 + 'px';
    });
    if (fontcounter == 3) {
      //disable the plus button
    }
    localStorage.setItem("fontcountsave", fontcounter);
  }
}

function decFunc() {
  var fontcounter = localStorage.getItem("fontcountsave");
  if (fontcounter > 0) {
    fontcounter--;
    $('*').css("font-size", function () {
      return parseInt($(this).css('font-size')) - 1 + 'px';
    });
    if (fontcounter == 0) {
      //disable the minus button
    }
    localStorage.setItem("fontcountsave", fontcounter);
  }
}
/*---------------------for language dropdown---------------------------*/
window.onload = function () {

  if (window.location.href.indexOf("/mca/global/hi/") > -1) {
    $('select#languagebox option:nth-child(2)').prop("selected", true);
  } else
    $('select#languagebox option:first').prop("selected", true);
}
/*--------------making the switch connection for all english pages to hindi pages indivudually-------------*/
$(document).ready(function () {
  var strVal = encrypt(window.location.href);
  $("#languagebox").on("change", function () {
    var ktmVal = $("#languagebox").val();
    if (ktmVal == "english") {
      var resVal = decrypt(decodeURIComponent(strVal));
      resVal = resVal.replace("/hi", "/en");
      window.location.href = resVal;
    } else {
      var resVal = decrypt(decodeURIComponent(strVal));
      resVal = resVal.replace("/en", "/hi");
      window.location.href = resVal;
    }
  })
});

document.addEventListener("DOMContentLoaded", function () {
  let langToggle = document.getElementById("languagebox");

  // Detect language from URL (recommended for AEM)
  let isHindi = window.location.pathname.includes("/hi");

  // Set toggle text
  langToggle.textContent = isHindi ? "English" : "हिन्दी";

  // Toggle click
  langToggle.addEventListener("click", function () {
    let currentPath = window.location.pathname;

    if (isHindi) {
      // Go to English
      window.location.href = currentPath.replace("/hi", "/en");
    } else {
      // Go to Hindi
      window.location.href = currentPath.replace("/en", "/hi");
    }
  });
});



$(document).ready(function () {
  $('.header-secondary #searchdiv #search-icon').on("click", function (e) {
    // use search.js behavior:
    if (typeof window.getSearchResult === "function") {
      window.getSearchResult(e);
      return false;
    }

    var windowwidth = decodeURIComponent($(window).width());
    if (windowwidth > 992) {
      e.preventDefault();
      $(this).closest("form")[0].submit();
    } else {
      $('.header-secondary .resp-search-box').css('display', 'block');
    }

  });

  $('.header-secondary #cancel-icon').on("click", function () {
    $('.header-secondary .resp-search-box').hide();
  });
});

$(window).on("resize", function () {
  if ($(window).width() > 575) {
    $('.header-secondary .resp-search-box').css('display', 'none');
  }
})

/*---------------------for refine search---------------------------*/
$('.searchbar #searchbox').keydown(function (e) {
  var key = e.which;
  if (key == 13) // the enter key code
  {
    $('.imgSearchIcon').click();
    return false;
  }
});

$('#refineLink').click(function () {
  $('.e-refineSearch').slideToggle(500);
});

$('.refinesearch #searchbox').click(function () {
  $(".e-refineSearch").slideUp();
});
